// 文字表記（音読み漢語）：二字漢語名詞とする動詞。同音異字・形近漢字の誤答を中心に構成。
Bank.group('write-b', '文字表記', [
  ['海外で働いた【けいけん】を活かして、今の仕事に就いた。', '経験', '軽験', '経検', '径験', '親身經歷過的事寫作「経験」。「経」是經過，「験」是驗證，「軽」「径」「検」都只是形近或同音的錯字。'],
  ['先生は文法のルールを図を使って【せつめい】してくれた。', '説明', '設明', '説名', '脱明', '把道理講清楚寫作「説明」。「説」有言字旁，與「設」「脱」形近，要小心。'],
  ['留学の【きかい】をもらって、とてもうれしかった。', '機会', '機械', '機回', '器会', '「機会（きかい）」是時機、機遇。「機械」雖然同音，指的是機器，放進「留学の機械」句意不通。'],
  ['最近は環境問題に【かんしん】を持つ人が増えている。', '関心', '感心', '観心', '完心', '「関心を持つ」表示感興趣、在意。「感心」指佩服讚嘆，不能搭配「持つ」。'],
  ['病院で【いし】に薬の飲み方を教えてもらった。', '医師', '意志', '意思', '遺志', '醫生寫作「医師」。「意志」是意志力，「意思」是想法、意向，同音但都不是人。'],
  ['この町は駅が多くて、【こうつう】が便利だ。', '交通', '公通', '交送', '校通', '電車、巴士等往來運輸寫作「交通」，「交」是交會，「通」是通行。'],
  ['長い間努力した【けっか】、ようやく試験に合格した。', '結果', '決果', '結課', '欠果', '事情最後的成果、後果寫作「結果」。「決」「欠」雖然也讀作「けつ」，但並不構成這個詞。'],
  ['結果だけでなく、そこにいたる【かてい】も大切にしたい。', '過程', '家庭', '課程', '仮定', '事物進行的經過寫作「過程」。「家庭」「課程」「仮定」都是同音詞，但放進「そこにいたる」句意不通。'],
  ['大学を卒業して、地元の銀行に【しゅうしょく】した。', '就職', '就織', '修職', '就識', '找到工作、開始上班寫作「就職」。「職」是職業，「織」「識」皆為形近字。'],
  ['電車は定刻どおり東京駅を【しゅっぱつ】した。', '出発', '出登', '出達', '出法', '離開出發地寫作「出発」。「発」常被誤寫成「登」或「達」。'],
  ['友達に新しい同僚を【しょうかい】してもらった。', '紹介', '招介', '照介', '紹会', '把人介紹給他人寫作「紹介」。「招」是招待，「照」是照射，與「紹」形近而易混。'],
  ['壊れた自転車を店で【しゅうり】してもらった。', '修理', '修里', '終理', '習理', '把壞掉的東西修好寫作「修理」。「修」的意思是修補，「里」是形近的錯字。'],
  ['サイズが合わなかったので、店で服を【こうかん】してもらった。', '交換', '交感', '公換', '交検', '以物換物、更換商品寫作「交換」。「交感」是同音的真實詞彙，但意思是互相感應，不能搭配「服を」。'],
  ['出かける前に、家族の分のお弁当を【ようい】した。', '用意', '容易', '要意', '用異', '事先準備好寫作「用意」。「容易」同音，意思是簡單，不能接「した」說成準備的意思。'],
  ['今日は【ようじ】があるので、先に帰ります。', '用事', '要事', '用時', '用字', '要處理的事情寫作「用事」。「用字」也念「ようじ」，但指用字遣詞，不符句意。'],
  ['毎朝三十分歩くのは、【けんこう】のためにいい。', '健康', '建康', '健庫', '検康', '身體狀況良好寫作「健康」。「健」與「建」形近，「建」是建造，需區分。'],
  ['子どもの帰りが遅くて、【しんぱい】で眠れなかった。', '心配', '心肺', '新配', '心記', '擔憂、掛念寫作「心配」。「心肺」雖然同音，指心臟與肺，無法表示擔心。'],
  ['この問題は条件が多くて、とても【ふくざつ】だ。', '複雑', '復雑', '複維', '複難', '內容錯綜、不單純寫作「複雑」。「複」是重疊，「復」是返回，常被搞混。'],
  ['最初は料理に【しっぱい】ばかりしていたが、今は上手になった。', '失敗', '失貝', '矢敗', '失数', '做不好、搞砸寫作「失敗」。「敗」的左旁是「貝」，與「失」組合成詞。'],
  ['何度も実験を重ねて、ついに【せいこう】した。', '成功', '精巧', '成効', '性功', '目標達成寫作「成功」。「精巧」是同音的真實詞，指做工精細，不能搭配「ついに〜した」。'],
  ['毎朝ジョギングをする【しゅうかん】がついた。', '習慣', '週間', '習間', '修慣', '長期養成的行為寫作「習慣」。「週間」同音，指一星期的期間，不能搭配「ジョギングをする」。'],
  ['隣の家とは、あまり【かんけい】がない。', '関係', '開係', '関保', '観係', '人或事物之間的聯繫寫作「関係」。「関」是門字框，與「開」形近，「係」不是「保」。'],
  ['将来は海外で働くことを【きぼう】している。', '希望', '希忘', '帰望', '気望', '想要實現的願望寫作「希望」。「帰」「気」只是讀音同為「き」，「忘」則是與「望」形近的錯字。'],
  ['怒りの【かんじょう】を抑えて、静かに話した。', '感情', '勘情', '観情', '感常', '喜怒哀樂等心中的情緒寫作「感情」。「感」是感受，「情」是情緒。'],
  ['インターネットで旅行の【じょうほう】を集めている。', '情報', '清報', '請報', '情宝', '資訊、消息寫作「情報」。「情」「清」「請」只差偏旁，要注意「情」是豎心旁「忄」。'],
  ['道路を渡るときは、車に【ちゅうい】してください。', '注意', '駐意', '中意', '注異', '留心小心寫作「注意」。「注」是灌注、集中，「駐」是停駐，「意」則不是「異」。'],
  ['人気の店なので、前もって【よやく】しておいた。', '予約', '余約', '予的', '予訳', '事先約定寫作「予約」。「予」是預先，「約」是約定。'],
  ['夏休みに家族で北海道へ行く【けいかく】を立てた。', '計画', '経画', '計書', '討画', '事先擬定的方案寫作「計画」。「計」是計算、打算，「画」是規劃。'],
  ['進路について、先生に【そうだん】した。', '相談', '想談', '相淡', '相段', '互相商量寫作「相談」。「談」有言字旁，與「淡」不同。'],
  ['授業のあとで、わからないところを先生に【しつもん】した。', '質問', '質門', '失問', '質聞', '提出疑問寫作「質問」。「問」的部件是「門」中放「口」，不是「聞」。'],
  ['メールを送ったが、まだ【へんじ】が来ない。', '返事', '変事', '返時', '返字', '回覆對方寫作「返事」。「変事」同音，指意外的事件，不適合接在「メール」之後。'],
  ['面接の前は【きんちょう】して、手が震えた。', '緊張', '緊帳', '禁張', '緊長', '精神繃緊、不安寫作「緊張」。「張」是拉緊，與「帳」「長」同音或形近。'],
  ['隣の部屋がうるさくて、勉強に【しゅうちゅう】できない。', '集中', '集仲', '収中', '終中', '把注意力集中在一處寫作「集中」。「集」是聚集，下方是「木」。'],
  ['彼がこんなに怒るとは、【そうぞう】もしなかった。', '想像', '創造', '創像', '相像', '在腦中設想寫作「想像」。「創造」同音，意思是創造，用在「〜もしなかった」不合理。'],
  ['週末は朝から部屋の【そうじ】をした。', '掃除', '掃徐', '帰除', '掃陰', '打掃寫作「掃除」。「掃」是掃帚的掃，「除」是去除。'],
  ['天気がいいので、週末に服を【せんたく】する。', '洗濯', '選択', '洗択', '先濯', '清洗衣物寫作「洗濯」。「選択」同音，意思是選擇，不能搭配「服を〜する」表示洗衣。'],
  ['道に迷っていたら、【しんせつ】な人が駅まで案内してくれた。', '親切', '新切', '親接', '身切', '待人溫和、肯幫忙寫作「親切」。「親」是親近，「切」是貼近。'],
  ['この辺りはバスが少なくて、とても【ふべん】だ。', '不便', '不変', '不使', '不辺', '沒有方便性寫作「不便」。「不変（ふへん）」讀音相近但不同，指不改變，與「バスが少ない」所帶來的困擾無關。'],
  ['時計が壊れて、【せいかく】な時間がわからない。', '正確', '性格', '正格', '生確', '沒有誤差、精準寫作「正確」。「性格」同音，是個性，不能修飾「時間」。'],
  ['兄は明るい【せいかく】で、友達が多い。', '性格', '正確', '性各', '生格', '一個人的個性寫作「性格」。「正確」同音，意思是準確，無法形容人的「明るい」特質。'],
  ['発表では、説明の【じゅんじょ】を考えてから話すようにしている。', '順序', '準序', '順叙', '順所', '先後次序寫作「順序」。「順」是順著，「序」是序列，與「準」不同。'],
  ['授業のあと、その日の内容を毎日【ふくしゅう】している。', '復習', '複習', '副習', '腹習', '把學過的東西再溫習一遍寫作「復習」。「復」是再度，常被誤寫為「複」。'],
  ['明日は朝九時に駅前に【しゅうごう】してください。', '集合', '収合', '習合', '集号', '大家聚在一處寫作「集合」。「集」是聚集，「合」是合在一起。'],
  ['どうぞ【えんりょ】しないで、たくさん食べてください。', '遠慮', '遠旅', '円慮', '遠憂', '客氣、顧慮寫作「遠慮」。「遠」是疏遠，「慮」是顧慮。'],
  ['今日はパソコンの【ちょうし】が悪くて、すぐ止まってしまう。', '調子', '長子', '調資', '彫子', '機器或身體的狀態寫作「調子」。「長子」同音，是長子，意思完全不同。'],
  ['連休で、高速道路が長く【じゅうたい】している。', '渋滞', '重体', '渋帯', '充滞', '車流不動寫作「渋滞」。「重体」同音，指病情危急，不能形容道路。'],
  ['試合に勝つ【じしん】があるので、練習は楽しかった。', '自信', '自身', '地震', '自心', '相信自己做得到寫作「自信」。「自身」是自己本身，「地震」是地震，兩者都不能搭配「ある」說成有把握。'],
  ['友達を誕生日パーティーに【しょうたい】した。', '招待', '正体', '紹待', '招持', '邀請他人參加寫作「招待」。「正体」同音，指真面目，不符句意。'],
  ['仕事の進み具合を、課長に【ほうこく】した。', '報告', '報苦', '包告', '防告', '把情況向上司說明寫作「報告」。「報」是通知，「告」是告知。'],
  ['熱を出した子どもを、一晩中【かんびょう】した。', '看病', '間病', '看痛', '観病', '照顧病人寫作「看病」。「看」是照看，不是「間」或「観」。'],
  ['足の骨を折って、二週間【にゅういん】した。', '入院', '入員', '入完', '人院', '住進醫院寫作「入院」。「入」與「人」形近，需要小心。'],
  ['病院で血液の【けんさ】を受けた。', '検査', '険査', '験査', '検差', '調查是否有異常寫作「検査」。「検」是木字旁，與「険」「験」形近。'],
  ['新しい星を【はっけん】したと、ニュースで知った。', '発見', '発件', '登見', '発健', '找到原本未知的事物寫作「発見」。「見」是看見，不是「件」或「健」。'],
  ['外国から来る観光客が、年々【ぞうか】している。', '増加', '増価', '憎加', '贈加', '數量變多寫作「増加」。「増」是增加，「加」是加上。'],
  ['この町では、子どもの数が【げんしょう】している。', '減少', '現象', '限少', '源少', '數量變少寫作「減少」。「現象」同音，指現象，不能搭配「数が〜している」。'],
  ['この町は十年で大きく【へんか】した。', '変化', '変価', '返化', '辺化', '狀態改變寫作「変化」。「変」是改變，「化」是變成。'],
  ['来週、仕事で大阪へ【しゅっちょう】する。', '出張', '出帳', '出長', '出調', '因公前往外地寫作「出張」。「張」不能換成同音的「帳」或形近的「長」。'],
  ['今日は仕事が多くて、夜まで【ざんぎょう】になった。', '残業', '残葉', '賛業', '残行', '在規定時間以外加班寫作「残業」。「残」是留下，「業」是工作。'],
  ['会議で、新しい企画を【ていあん】した。', '提案', '提安', '堤案', '定案', '向他人提出構想寫作「提案」。「提」是提出，「案」是方案。'],
  ['アルバイトの【しゅうにゅう】で、新しいカメラを買った。', '収入', '終入', '収人', '修入', '賺到的錢寫作「収入」。「収」是收取，「入」是進入，與「人」形近。'],
  ['留守の間に、【ゆうびん】で荷物が届いたようだ。', '郵便', '郵使', '優便', '郵偏', '利用郵局寄送物品寫作「郵便」。「便」在此指傳遞、送達。'],
  ['私は小さいころから、歴史に【きょうみ】がある。', '興味', '共味', '強味', '興未', '想深入了解的心情寫作「興味」。「興」是興致，「味」是滋味。'],
  ['失敗したのは私の【せきにん】だから、最後まで自分で直す。', '責任', '積任', '責仕', '債任', '必須承擔的義務或過失寫作「責任」。「責」是責備、承擔，與「積」「債」形近。'],
  ['店の前に車を【ちゅうしゃ】してはいけません。', '駐車', '注射', '注車', '駐者', '把車子停下來寫作「駐車」。「注射」同音，指打針，放進「車を〜する」句意不通。'],
  ['海外でけがをしたときのために、旅行の前に【ほけん】に入った。', '保険', '保健', '保検', '保験', '為意外風險投保的契約寫作「保険」。「保健」同音，指維護健康，不能搭配「に入る」表示投保。'],
  ['電車は五分ごとの【かんかく】で駅に来る。', '間隔', '感覚', '関覚', '間格', '兩者之間相隔的時間或距離寫作「間隔」。「感覚」同音，指感官的感受，不能搭配「五分ごとの」。'],
  ['映画を見た【かんそう】を、友達に話した。', '感想', '乾燥', '間想', '観想', '看了或聽了後的感受寫作「感想」。「乾燥」同音，指乾燥，不能搭配「映画を見た」。'],
  ['この書類は【じゅうよう】だから、なくさないでください。', '重要', '重用', '住要', '重曜', '很要緊、不可忽略寫作「重要」。「重用」同音，指重用人才，不能形容書類。'],
  ['海外からのお客様を、拍手で【かんげい】した。', '歓迎', '観迎', '歓逆', '勧迎', '熱情迎接寫作「歓迎」。「歓」右邊是「欠」，「観」「勧」右邊分別是「見」「力」，「迎」是迎接。'],
  ['車を運転するときは、いつも【あんぜん】に気をつけている。', '安全', '完全', '案全', '安金', '沒有危險寫作「安全」。「完全」是完整無缺，形近但讀作「かんぜん」，且語意不合。']
]);
